description: Match link bores to motor bores to count arm fastener positions
command: cd /home/inaho-omen/Project/3d-printed-dynamixel-gripper && S=/tmp/claude-1000/-home-inaho-omen-Project-low-cost-robot/0b891917-c2aa-4eef-9022-6e2c4183202a/scratchpad && cat > $S/arm_fasteners.py <<'EOF'
import sys, re, math, collections, json
import numpy as np
sys.path.insert(0, '.')
from OCP.BRepAdaptor import BRepAdaptor_Surface
from cadre.probes import cylinder_surface_sense
from scripts.step_cache import read_rows
from scripts.assembly_io import bounds

rows = read_rows("outputs/camera-mount-id5-overhead-d405-r5/CAD/ID5_D405_mid_ASSEMBLY.step")
shapes = {r.name: r.world for r in rows}

def bores(shape, rmin=0.9, rmax=1.8):
    out = []
    for f in shape.Faces():
        if f.geomType() != "CYLINDER":
            continue
        c = BRepAdaptor_Surface(f.wrapped).Cylinder()
        r = c.Radius()
        if not (rmin <= r <= rmax):
            continue
        try:
            if cylinder_surface_sense(f) != "concave":
                continue
        except Exception:
            continue
        a = c.Axis(); d = np.array([a.Direction().X(), a.Direction().Y(), a.Direction().Z()])
        p = np.array([a.Location().X(), a.Location().Y(), a.Location().Z()])
        b = bounds(f); pts = np.array([b[:3], b[3:]])
        span = sorted(float(v @ d) for v in pts)
        out.append({"r": r, "d": d, "p": p, "span": span})
    return out

def same_axis(a, b, tol=0.05):
    if abs(abs(a["d"] @ b["d"]) - 1) > 1e-4:
        return False
    v = b["p"] - a["p"]
    return np.linalg.norm(v - (v @ a["d"]) * a["d"]) < tol

motors = collections.defaultdict(list)
for n, s in shapes.items():
    m = re.match(r"ARM_(M0\d)_ref(\d+)", n)
    if m:
        for b in bores(s, 0.95, 1.1):
            b["occ"] = n; motors[m.group(1)].append(b)
    if n == "PG3_XL430_fixed":
        for b in bores(s, 0.95, 1.1):
            b["occ"] = n; motors["M05(PG3_XL430_fixed)"].append(b)
links = {n: s for n, s in shapes.items() if re.match(r"ARM_P0\d", n)}
report = []
for ln, ls in sorted(links.items()):
    lb = bores(ls, 0.9, 1.8)
    used = set()
    for mn, mb in sorted(motors.items()):
        hits = []
        for i, b in enumerate(lb):
            if i in used:
                continue
            match = [m for m in mb if same_axis(b, m) and abs(b["r"] - m["r"]) < 1.0]
            if match:
                used.add(i)
                hits.append((b, match[0]))
        if hits:
            groups = collections.defaultdict(list)
            for b, m in hits:
                groups[(m["occ"], round(2 * m["r"], 2), round(2 * b["r"], 2))].append(b)
            for (occ, md, bd), bs in groups.items():
                axes = sorted({tuple(np.round(np.abs(x["d"]), 3)) for x in bs})
                lengths = sorted({round(x["span"][1] - x["span"][0], 2) for x in bs})
                report.append({"link": ln, "motor": mn, "motor_occ": occ, "motor_bore_d": md,
                               "link_bore_d": bd, "count": len(bs), "axis": axes, "link_bore_len_mm": lengths})
for r in report:
    print(f"{r['link']:28s} {r['motor']:22s} {r['motor_occ']:18s} motor_d={r['motor_bore_d']:<5} link_d={r['link_bore_d']:<5} n={r['count']:2d} link_len={r['link_bore_len_mm']} axis={r['axis']}")
json.dump(report, open(sys.argv[1], "w"), indent=1, default=str)
EOF
