"""Generate a URDF tree and one new world-frame mesh per declared rigid link."""

import hashlib
import json
import re
import warnings
import xml.etree.ElementTree as ET
from collections import Counter
from pathlib import Path

import numpy as np
from scipy.spatial.transform import Rotation


def matrix(frame):
    result = np.asarray(frame, dtype=float)
    if result.shape != (4, 4) or not np.isfinite(result).all():
        raise ValueError("frame_m must be a finite 4x4 matrix")
    if not np.allclose(result[3], [0, 0, 0, 1], atol=1e-12):
        raise ValueError("Invalid homogeneous frame")
    r = result[:3, :3]
    if not np.allclose(r.T @ r, np.eye(3), atol=1e-10) or not np.isclose(
        np.linalg.det(r), 1, atol=1e-10
    ):
        raise ValueError("Frame rotation must be orthonormal, without scale/reflection")
    return result


def number_text(values):
    return " ".join(format(float(v), ".17g") for v in values)


def add_origin(parent, transform):
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", message="Gimbal lock detected.*")
        angles = Rotation.from_matrix(transform[:3, :3]).as_euler("xyz")
    ET.SubElement(
        parent, "origin", xyz=number_text(transform[:3, 3]), rpy=number_text(angles)
    )


def validate_config(config, rows):
    if config.get("schema_version") != 1 or config.get("length_unit") != "m":
        raise ValueError("Require schema_version=1 and length_unit=m")
    links = config["links"]
    if not links or config["root"] not in links:
        raise ValueError("Missing root link")
    for name in [config["robot_name"], *links]:
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            raise ValueError(f"Unsafe/invalid robot or link name: {name}")
    frames = {name: matrix(link["frame_m"]) for name, link in links.items()}
    metadata = config.get("metadata_occurrences", [])
    if len(metadata) != len(set(metadata)) or not set(metadata) <= {
        r.index for r in rows
    }:
        raise ValueError("Invalid metadata occurrence indices")
    assigned = {name: [] for name in links}
    for row in rows:
        if row.index in metadata:
            continue
        matches = []
        for name, spec in links.items():
            selectors = spec.get("parts", [])
            for selector in selectors:
                if isinstance(selector, str):
                    match = selector == row.name
                else:
                    match = (
                        selector.get("index") == row.index
                        and selector.get("name") == row.name
                    )
                if match:
                    matches.append(name)
        if len(matches) != 1:
            raise ValueError(
                f"Occurrence {row.index}:{row.name} has {len(matches)} assignments"
            )
        assigned[matches[0]].append(row)
    for name, spec in links.items():
        if len(assigned[name]) != spec["expected_occurrences"]:
            raise ValueError(f"Occurrence count mismatch for {name}")
    children = []
    joint_names = []
    for joint in config["joints"]:
        parent, child = joint["parent"], joint["child"]
        if parent not in links or child not in links or parent == child:
            raise ValueError("Invalid joint endpoints")
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", joint["name"]):
            raise ValueError("Invalid joint name")
        children.append(child)
        joint_names.append(joint["name"])
        if joint["type"] not in ("fixed", "revolute", "continuous", "prismatic"):
            raise ValueError("Unsupported URDF joint type")
        if joint["type"] != "fixed":
            axis = np.asarray(joint["axis"], dtype=float)
            if (
                axis.shape != (3,)
                or not np.isfinite(axis).all()
                or not np.isclose(np.linalg.norm(axis), 1)
            ):
                raise ValueError("Joint axis must be a unit vector")
            limit = joint.get("limit")
            required = (
                ("effort", "velocity")
                if joint["type"] == "continuous"
                else ("lower", "upper", "effort", "velocity")
            )
            if not isinstance(limit, dict) or any(k not in limit for k in required):
                raise ValueError(
                    "Explicit joint limits are required; fill the inferred config"
                )
            if not all(np.isfinite(limit[k]) for k in required):
                raise ValueError("Nonfinite joint limit")
            if (
                limit["effort"] < 0
                or limit["velocity"] < 0
                or ("lower" in limit and limit["lower"] > limit["upper"])
            ):
                raise ValueError("Invalid joint limits")
    if len(children) != len(set(children)) or len(joint_names) != len(set(joint_names)):
        raise ValueError("Duplicate parent or joint name")
    if set(links) - set(children) != {config["root"]}:
        raise ValueError("Require exactly one declared root")
    reached = {config["root"]}
    while True:
        new = {j["child"] for j in config["joints"] if j["parent"] in reached}
        if new <= reached:
            break
        reached |= new
    if reached != set(links):
        raise ValueError("Disconnected or cyclic joint tree")
    return frames, assigned


def write_mesh(rows, path, linear_deflection_mm, angular_deflection_rad):
    from OCC.Core.BRep import BRep_Builder
    from OCC.Core.BRepBuilderAPI import BRepBuilderAPI_Transform
    from OCC.Core.BRepMesh import BRepMesh_IncrementalMesh
    from OCC.Core.gp import gp_Pnt, gp_Trsf
    from OCC.Core.StlAPI import StlAPI_Writer
    from OCC.Core.TopoDS import TopoDS_Compound

    compound = TopoDS_Compound()
    builder = BRep_Builder()
    builder.MakeCompound(compound)
    for row in rows:
        builder.Add(compound, row.world)
    scale = gp_Trsf()
    scale.SetScale(gp_Pnt(), 0.001)
    scaled = BRepBuilderAPI_Transform(compound, scale, True).Shape()
    mesh = BRepMesh_IncrementalMesh(
        scaled, linear_deflection_mm / 1000, False, angular_deflection_rad, True
    )
    if not mesh.IsDone():
        raise ValueError(f"Meshing failed: {path}")
    writer = StlAPI_Writer()
    writer.SetASCIIMode(False)
    if not writer.Write(scaled, str(path)):
        raise ValueError(f"STL write failed: {path}")
    if not path.is_file() or path.stat().st_size < 84:
        raise ValueError("Empty STL output")


def convert(step, config, output, rows, inv, versions):
    frames, groups = validate_config(config, rows)
    output = Path(output)
    # No implicit recursive deletion or replacement of existing exports.
    if output.exists() and any(output.iterdir()):
        raise FileExistsError(f"Output must be empty: {output}")
    output.mkdir(parents=True, exist_ok=True)
    assets = output / "assets"
    assets.mkdir()
    linear = float(config.get("linear_deflection_mm", 0.1))
    angular = float(config.get("angular_deflection_rad", 0.1))
    if not np.isfinite([linear, angular]).all() or linear <= 0 or angular <= 0:
        raise ValueError("Mesh deflections must be finite and positive")
    robot = ET.Element("robot", name=config["robot_name"])
    robot.append(
        ET.Comment(
            "Geometric model; mass, inertia and actuator ratings are not inferred from STEP."
        )
    )
    mesh_reports = {}
    for name, link in config["links"].items():
        element = ET.SubElement(robot, "link", name=name)
        if not groups[name]:
            continue
        mesh_path = assets / f"{name}.stl"
        write_mesh(groups[name], mesh_path, linear, angular)
        for tag in ("visual", "collision"):
            visual = ET.SubElement(element, tag)
            add_origin(visual, np.linalg.inv(frames[name]))
            ET.SubElement(
                ET.SubElement(visual, "geometry"), "mesh", filename=f"assets/{name}.stl"
            )
            if tag == "visual":
                material = ET.SubElement(visual, "material", name=f"{name}_material")
                color = link.get("color_rgba", [0.7, 0.7, 0.7, 1])
                ET.SubElement(material, "color", rgba=number_text(color))
        mesh_reports[name] = {
            "path": f"assets/{name}.stl",
            "sha256": hashlib.sha256(mesh_path.read_bytes()).hexdigest(),
            "occurrence_indices": [r.index for r in groups[name]],
            "occurrence_names": dict(Counter(r.name for r in groups[name])),
        }
    for joint in config["joints"]:
        element = ET.SubElement(robot, "joint", name=joint["name"], type=joint["type"])
        ET.SubElement(element, "parent", link=joint["parent"])
        ET.SubElement(element, "child", link=joint["child"])
        add_origin(
            element, np.linalg.inv(frames[joint["parent"]]) @ frames[joint["child"]]
        )
        if joint["type"] != "fixed":
            ET.SubElement(element, "axis", xyz=number_text(joint["axis"]))
            ET.SubElement(
                element,
                "limit",
                **{k: format(float(v), ".17g") for k, v in joint["limit"].items()},
            )
    tree = ET.ElementTree(robot)
    ET.indent(tree, space="  ")
    tree.write(output / "robot.urdf", encoding="utf-8", xml_declaration=True)
    report = {
        "status": "CONVERTED_KINEMATIC_VALIDATION_PENDING",
        "versions": versions,
        "input_sha256": hashlib.sha256(Path(step).read_bytes()).hexdigest(),
        "reader_unit": "mm",
        "mesh_and_urdf_unit": "m",
        "links": len(frames),
        "joints": len(config["joints"]),
        "occurrences": len(rows),
        "meshes": mesh_reports,
        "inventory": inv,
        "limitations": [
            "No inferred mass/inertia or hardware ratings",
            "Closed loops require explicit external coupling",
            "STL collision surfaces are not guaranteed solid or convex",
        ],
    }
    (output / "conversion.json").write_text(json.dumps(report, indent=2) + "\n")
    (output / "config.json").write_text(json.dumps(config, indent=2) + "\n")
    return report


