from OCC.Core.TopLoc import TopLoc_Location
from OCC.Core.TopoDS import TopoDS_Compound
from OCC.Core.XCAFDoc import XCAFDoc_DocumentTool

from urdf_from_step.cli import main, versions
from urdf_from_step.converter import convert, validate_config
from urdf_from_step.occ_reader import inventory, read_step


def fixture_step(path, unit="MM"):
    doc = TDocStd_Document("test")
    st = XCAFDoc_DocumentTool.ShapeTool(doc.Main())
    root, nested = st.NewShape(), st.NewShape()
    TDataStd_Name.Set(root, "Fixture")
    TDataStd_Name.Set(nested, "nested")
    box = st.AddShape(BRepPrimAPI_MakeBox(25.4, 2, 3).Shape(), False)
    TDataStd_Name.Set(box, "bolt")
    # Include two instances at exactly the same position: names/topology are not IDs.
    for offset in (0, 10, 0):
        transform = gp_Trsf()
        transform.SetTranslation(gp_Vec(offset, 0, 0))
        label = st.AddComponent(nested, box, TopLoc_Location(transform))
        TDataStd_Name.Set(label, "bolt")
    transform = gp_Trsf()
    transform.SetRotation(gp_Ax1(gp_Pnt(), gp_Dir(0, 0, 1)), np.pi / 2)
    transform.SetTranslationPart(gp_Vec(100, 20, 30))
    label = st.AddComponent(root, nested, TopLoc_Location(transform))
    TDataStd_Name.Set(label, "rotated_subassembly")
    compound = TopoDS_Compound()
    builder = BRep_Builder()
    builder.MakeCompound(compound)
    builder.Add(compound, BRepPrimAPI_MakeBox(2, 3, 4).Shape())
    builder.Add(compound, BRepPrimAPI_MakeBox(gp_Pnt(10, 0, 0), 1, 1, 1).Shape())
    multi = st.AddShape(compound, False)
    TDataStd_Name.Set(multi, "multi")
    label = st.AddComponent(root, multi, TopLoc_Location())
    TDataStd_Name.Set(label, "multi")
    st.UpdateAssemblies()
    writer = STEPCAFControl_Writer()
    assert Interface_Static.SetCVal("write.step.unit", unit)
    assert writer.Transfer(doc, STEPControl_AsIs)
    assert writer.Write(str(path)) == 1
    return path


