def test_mesh_scale_inventory_and_existing_output_guard(tmp_path):
    path = fixture_step(tmp_path / "fixture.step")
    _doc, rows = read_step(path)
    out = tmp_path / "robot"
    report = convert(path, config(), out, rows, inventory(rows), versions())
    mesh = trimesh.load_mesh(out / "assets/base.stl", process=False)
    np.testing.assert_allclose(
